import * as THREE from './vendor/three.module.js';
export const TILE=4,SIZE=48,HALF=96;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),smooth=t=>t*t*(3-2*t);
function hash(x,y,seed){let v=Math.imul(x,374761393)+Math.imul(y,668265263)+seed*31;v=Math.imul(v^(v>>>13),1274126177);return((v^(v>>>16))>>>0)/4294967295}
function noise(x,y,seed){const a=Math.floor(x),b=Math.floor(y),u=smooth(x-a),v=smooth(y-b);return THREE.MathUtils.lerp(THREE.MathUtils.lerp(hash(a,b,seed),hash(a+1,b,seed),u),THREE.MathUtils.lerp(hash(a,b+1,seed),hash(a+1,b+1,seed),u),v)}
function wetTile(w,x,y){if(x>=0&&y>=0&&x<SIZE&&y<SIZE)return w.tiles[y*SIZE+x].ground==='water'?1:0;if(w.terrain==='river')return Math.abs(x-(34+Math.sin(y/7+w.seed%9)*3))<2.3?1:0;if(w.terrain==='islands')return Math.sin(x/7)+Math.cos(y/8)+Math.sin((x+y)/9)>1.05?1:0;return 0}
const waterFields=new WeakMap();
function field(w){if(waterFields.has(w))return waterFields.get(w);const f=new Float32Array(52*52),weights=[.18,.64,.18];for(let y=-2;y<50;y++)for(let x=-2;x<50;x++){let v=0;for(let j=-1;j<=1;j++)for(let i=-1;i<=1;i++)v+=wetTile(w,x+i,y+j)*weights[i+1]*weights[j+1];f[(y+2)*52+x+2]=v}waterFields.set(w,f);return f}
export function wetness(w,x,z){const gx=(x+HALF)/TILE-.5,gy=(z+HALF)/TILE-.5;if(w.terrain==='river'){const distance=Math.abs(gx-(34+Math.sin(gy/7+w.seed%9)*3));return smooth(clamp((3.35-distance)/2.1,0,1))}if(w.terrain==='islands'){const level=Math.sin(gx/7)+Math.cos(gy/8)+Math.sin((gx+gy)/9);return smooth(clamp((level-.72)/.65,0,1))}return 0}
function valleyFalloff(w,x,z){if(w.terrain==='river'){const gx=(x+96)/4-.5,gy=(z+96)/4-.5,d=Math.abs(gx-(34+Math.sin(gy/7+w.seed%9)*3))*4;return smooth(clamp((d-10)/65,0,1))}return 1-smooth(clamp(wetness(w,x,z)*3,0,1))}
export function groundHeight(w,x,z){const water=wetness(w,x,z),inland=.35+noise(x*.012,z*.012,w.seed)*1.6+noise(x*.028,z*.028,w.seed+3)*.7+noise(x*.09,z*.09,w.seed+17)*.12;const edge=smooth(clamp((Math.hypot(x,z)-100)/260,0,1)),ridge=Math.pow(1-Math.abs(noise(x*.007,z*.007,w.seed+8)*2-1),2),hills=edge*(ridge*30+noise(x*.016,z*.016,w.seed+11)*7),bank=smooth(clamp(water*1.85,0,1));return inland*(1-bank)+hills*valleyFalloff(w,x,z)-bank*1.6;}
export function terrainColor(w,x,z){const wet=wetness(w,x,z),variation=noise(x*.037,z*.037,w.seed+51),c=new THREE.Color('#c8e0ad').lerp(new THREE.Color('#d4dfb3'),variation*.7);c.lerp(new THREE.Color('#c3bda6'),smooth(clamp(wet*3,0,1)));const slope=Math.abs(groundHeight(w,x+1,z)-groundHeight(w,x-1,z))+Math.abs(groundHeight(w,x,z+1)-groundHeight(w,x,z-1));c.lerp(new THREE.Color('#959a8d'),clamp((slope-1.2)*.28,0,.8));return c.multiplyScalar(.93+noise(x*.14,z*.14,w.seed+21)*.13)}
export function floorHeight(w,x,z){return Math.max(.2,groundHeight(w,x,z))}
export class Landscape{
constructor(view){this.view=view;this.group=new THREE.Group();view.scene.add(this.group);this.loader=new THREE.TextureLoader();this.assets={};this.ready=this.load();}
async load(){const defs=['grass-color','grass-normal','grass-rough','asphalt-color','asphalt-normal','asphalt-rough','brick-color','brick-normal','brick-rough'];await Promise.all(defs.map(async name=>{try{const t=await this.loader.loadAsync(new URL('./assets/'+name+'.jpg',import.meta.url).href);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=this.view.renderer.capabilities.getMaxAnisotropy();if(name.endsWith('color'))t.colorSpace=THREE.SRGBColorSpace;this.assets[name]=t}catch(e){console.warn('Texture fallback:',name)}}));}
material(name,repeat=1,color='#ffffff'){const map=this.assets[name+'-color']?.clone(),normal=this.assets[name+'-normal']?.clone(),rough=this.assets[name+'-rough']?.clone();for(let t of [map,normal,rough])if(t){t.repeat.set(repeat,repeat);t.needsUpdate=true}return new THREE.MeshStandardMaterial({color,map:map||null,normalMap:normal||null,roughnessMap:rough||null,normalScale:new THREE.Vector2(.3,.3),roughness:.92});}
clear(){this.group.traverse(o=>{if(o.geometry&&!o.userData.sharedAsset)o.geometry.dispose();if(o.material&&!o.userData.sharedMaterial){for(let m of Array.isArray(o.material)?o.material:[o.material]){if(m===this.leafMat||[...this.view.materials.values()].includes(m))continue;for(let k of ['map','normalMap','roughnessMap'])if(m[k]&&!Object.values(this.assets).includes(m[k]))m[k].dispose();m.dispose()}}});this.group.clear()}
build(w){this.clear();this.world=w;const geo=new THREE.PlaneGeometry(192,192,192,192);geo.rotateX(-Math.PI/2);const pos=geo.attributes.position,colors=[];for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),h=groundHeight(w,x,z),wet=wetness(w,x,z);pos.setY(i,h);const col=terrainColor(w,x,z);colors.push(col.r,col.g,col.b)}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const mat=this.material('grass',14,'#ffffff');mat.vertexColors=true;mat.normalScale.set(.55,.55);this.ground=new THREE.Mesh(geo,mat);this.ground.receiveShadow=true;this.group.add(this.ground);
const far=new THREE.PlaneGeometry(1100,1100,400,400);far.rotateX(-Math.PI/2);const fp=far.attributes.position;for(let i=0;i<fp.count;i++)fp.setY(i,groundHeight(w,fp.getX(i),fp.getZ(i))-.1);let ind=[];const arr=far.index.array;for(let i=0;i<arr.length;i+=3){let x=0,z=0;for(let j=0;j<3;j++){x+=fp.getX(arr[i+j])/3;z+=fp.getZ(arr[i+j])/3}if(Math.abs(x)>95||Math.abs(z)>95)ind.push(arr[i],arr[i+1],arr[i+2])}far.setIndex(ind);far.computeVertexNormals();const farColors=[];for(let i=0;i<fp.count;i++){const x=fp.getX(i),z=fp.getZ(i),c=terrainColor(w,x,z);farColors.push(c.r,c.g,c.b)}far.setAttribute('color',new THREE.Float32BufferAttribute(farColors,3));const fm=this.material('grass',80.2083,'#ffffff');fm.vertexColors=true;this.surroundings=new THREE.Mesh(far,fm);this.surroundings.receiveShadow=true;this.group.add(this.surroundings);
this.waterMaterial=new THREE.ShaderMaterial({uniforms:{time:{value:0},sun:{value:new THREE.Vector3(-.4,.75,.35)},night:{value:0}},vertexShader:`varying vec3 worldPos;varying vec3 viewDir;void main(){vec4 p=modelMatrix*vec4(position,1.);worldPos=p.xyz;viewDir=cameraPosition-p.xyz;gl_Position=projectionMatrix*viewMatrix*p;}`,fragmentShader:`precision highp float;uniform float time;uniform float night;uniform vec3 sun;varying vec3 worldPos;varying vec3 viewDir;void main(){vec2 p=worldPos.xz;float a=sin(p.x*2.3+p.y*.71+time*.7)*.5+sin(p.x*4.17-p.y*2.9+time*.5)*.3,b=cos(p.x*1.17-p.y*2.21-time*.85)*.5+sin(p.x*3.8+p.y*1.9+time*.4)*.3;vec3 n=normalize(vec3(a*.065,1.,b*.08));vec3 v=normalize(viewDir);float fres=pow(1.-max(dot(v,n),0.),3.);float glint=pow(max(dot(reflect(-normalize(sun),n),v),0.),110.);float ripple=.5+.25*sin(p.x*.15+time*.1)+.25*cos(p.y*.19-time*.13);vec3 deep=mix(vec3(.075,.15,.16),vec3(.15,.24,.24),ripple*.3);vec3 c=mix(deep,vec3(.15,.25,.28),fres*.5)+glint*.16;c=mix(c,c*.32,night);gl_FragColor=vec4(c,1.);}`,side:THREE.DoubleSide});this.water=new THREE.Mesh(new THREE.PlaneGeometry(1100,1100),this.waterMaterial);this.water.rotation.x=-Math.PI/2;this.water.position.y=-.1;this.group.add(this.water);this.makeTrees(w);this.makeRocks(w);}
leafMaterial(){if(this.leafMat)return this.leafMat;const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d');for(let i=0;i<380;i++){let a=i*2.39996,r=Math.sqrt(i/380)*59,x=64+Math.cos(a)*r,y=64+Math.sin(a)*r;ctx.fillStyle=['#6c8047','#70874d','#526a36','#8a9659'][i%4];ctx.beginPath();ctx.ellipse(x,y,2.3+(i%3),1.5+(i%2),a,0,Math.PI*2);ctx.fill()}const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;this.leafMat=new THREE.MeshStandardMaterial({map:tex,alphaTest:.45,side:THREE.DoubleSide,roughness:1,envMapIntensity:.1});return this.leafMat}
makeTrees(w){const positions=[];w.tiles.forEach((t,i)=>{if(t.tree&&!t.type&&t.ground==='land'){const x=(i%48+.5)*4-96,z=(Math.floor(i/48)+.5)*4-96;for(let j=0;j<2;j++){const px=x+hash(i,j,w.seed)*3-1.5,pz=z+hash(j,i,w.seed)*3-1.5;if(wetness(w,px,pz)<.18)positions.push([px,pz,2.8+hash(i,j+3,w.seed)*2,i%4])}}});// Small neighborhood trees soften developed block interiors without hiding roads.
for(let i=0;i<w.tiles.length;i++){const t=w.tiles[i];if(t.type||t.zone||t.ground!=='land'||t.tree)continue;const neighbors=CityEngine.neighbors(i);if(neighbors.some(j=>['residential','commercial','office'].includes(w.tiles[j].type))&&!neighbors.some(j=>w.tiles[j].type==='road')&&hash(i,307,w.seed)>.4){const x=(i%48+.5)*4-96,z=(Math.floor(i/48)+.5)*4-96;positions.push([x,z,1.9+hash(i,311,w.seed)*1.2,i%4])}}
for(let k=0;k<1500;k++){const x=hash(k,77,w.seed)*640-320,z=hash(k,83,w.seed)*640-320;if(Math.abs(x)<98&&Math.abs(z)<98||Math.abs(z-2)<4&&x<0||wetness(w,x,z)>.08||noise(x*.017,z*.017,w.seed+7)<.42)continue;positions.push([x,z,4+hash(k,91,w.seed)*4,k%4])}const realistic=this.view.vegetation.populate(this.group,positions,(x,z)=>floorHeight(w,x,z));if(realistic){this.trees=realistic;return}const trunk=new THREE.InstancedMesh(new THREE.CylinderGeometry(.045,.12,1,7),this.view.mat('#746958'),positions.length),leaves=new THREE.InstancedMesh(new THREE.PlaneGeometry(1,1),this.leafMaterial(),positions.length*24);const d=new THREE.Object3D();positions.forEach(([x,z,h,v],i)=>{const y=floorHeight(w,x,z);d.rotation.set(0,0,0);d.position.set(x,y+h*.43,z);d.scale.set(1,h*.85,1);d.updateMatrix();trunk.setMatrixAt(i,d.matrix);for(let j=0;j<24;j++){const a=j*2.399+i,r=Math.sqrt((j%8)/8)*h*.24;d.position.set(x+Math.cos(a)*r,y+h*.55+Math.sin(j*1.7)*h*.13+(j%3)*h*.08,z+Math.sin(a)*r);d.rotation.set((j%3-1)*.45,a,(j%2)*.25);const size=h*(.42+(j%4)*.035);d.scale.set(size,size*(j%2?.9:1.1),1);d.updateMatrix();leaves.setMatrixAt(i*24+j,d.matrix);const col=new THREE.Color(['#b9cba4','#95b09c','#c7cfa7','#acc294'][v]);leaves.setColorAt(i*24+j,col)}});trunk.castShadow=true;leaves.castShadow=true;leaves.receiveShadow=true;this.group.add(trunk,leaves);this.trees=[trunk,leaves]}

makeRocks(w){const points=[];for(let k=0;k<1700;k++){const x=hash(k,131,w.seed)*470-235,z=hash(k,139,w.seed)*470-235,wet=wetness(w,x,z);if(wet<.12||wet>.45||Math.abs(z-2)<5&&x<0)continue;const ix=Math.floor((x+96)/4),iy=Math.floor((z+96)/4);if(ix>=0&&iy>=0&&ix<48&&iy<48&&w.tiles[iy*48+ix].type)continue;points.push([x,z,.15+hash(k,143,w.seed)*.5])}const geo=new THREE.IcosahedronGeometry(1,2),a=geo.attributes.position;for(let i=0;i<a.count;i++){const v=1+.16*Math.sin(a.getX(i)*8+a.getY(i)*7+a.getZ(i)*5);a.setXYZ(i,a.getX(i)*v,a.getY(i)*v,a.getZ(i)*v)}geo.computeVertexNormals();const mesh=new THREE.InstancedMesh(geo,this.view.mat('#87897c'),points.length),d=new THREE.Object3D();points.forEach(([x,z,r],i)=>{d.position.set(x,groundHeight(w,x,z)+r*.23,z);d.scale.set(r*1.4,r*.65,r);d.rotation.set(i*.31,i*.77,0);d.updateMatrix();mesh.setMatrixAt(i,d.matrix);mesh.setColorAt(i,new THREE.Color().setHSL(.14,.06,.68+(i%5)*.035))});mesh.castShadow=true;mesh.receiveShadow=true;this.group.add(mesh)}

refreshTrees(w){for(let o of this.trees||[]){this.group.remove(o);o.dispose?.();o.traverse(m=>{if(m.geometry&&!m.userData.sharedAsset)m.geometry.dispose()})}this.makeTrees(w)}
update(time,night){if(this.waterMaterial){this.waterMaterial.uniforms.time.value=time;this.waterMaterial.uniforms.night.value=night?1:0}}
}
